"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-0899-01-01:0":{"b": ["उरार्तू राज्य (तुश्पा / वान): उरार्तू राज्य बनता है (9वीं शताब्दी)", "3dec342f"], "d": ["उरार्तू राज्य ई.पू. 9वीं शताब्दी में बनता है। अश्शूरी स्रोतों में शल्मनेसर तृतीय के आरमे से युद्ध; सरदूरी प्रथम (लुतिप्री का पुत्र) तुश्पा को राजधानी बनाता है।", "72d6f79a"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1190-01-01:0":{"b": ["उगारित राज्य (गिबाला/तेल तवेइनी) — समुद्री जातियों द्वारा विध्वंस: उगारित/तेल तवेइनी नष्ट होता है (समुद्री जातियों का युग)", "eb558ed2"], "d": ["उत्तरी लेवांत (गिबाला, उगारित, रास इब्न हानी, तेल काज़ेल) में कांस्य युग के अंत के विनाश; 14C भारित औसत (2962±14 बी.पी.) + KTU 1.78 सूर्यग्रहण (21 जनवरी 1192) के ढाँचे में 1192-1190 कैलिब्रेटेड ई.पू.।", "720ed864"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1199-01-01:0":{"b": ["हत्तुसा का ख़ाली किया जाना: हत्तुसा त्यागा जाता है; हित्ती साम्राज्य ढहता है (लगभग 1200)", "1d0de530"], "d": ["केंद्रीय प्रशासन ने हत्तुसा को ख़ाली कर दिया था, नगर केवल बाद में जलाया गया; सूखा (1198-1196±3) पतन की परिस्थितियों का भाग हो सकता है, सिद्ध कारण-संबंध नहीं है।", "a91c1bfb"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1206-01-01:0":{"b": ["सुप्पिलुलियुमा द्वितीय (अंतिम ज्ञात हित्ती राजा) — राज्यारोहण: सुप्पिलुलियुमा द्वितीय सिंहासनारूढ़ होता है (अंतिम हित्ती राजा)", "b2ef7227"], "d": ["अंतिम ज्ञात हित्ती राजा का शासन ई.पू. ~1207 में आरंभ होता है; हित्ती साम्राज्य और उसका केंद्रीय प्रशासन 'around or shortly after 1200' ढहता है; टर्मिनस ऐंते क्वेम रामसेस तृतीय का 8वाँ वर्ष (मेदीनेत हाबू)।", "77bdf879"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1583-01-01:0":{"b": ["थेरा (सेंटोरिनी) मिनोआई विस्फोट — वर्तमान बेज़ियन मॉडल: थेरा (सेंटोरिनी) विस्फोट — मैनिंग 2022 मॉडल", "a63eeb92"], "d": ["विस्फोट इंटकैल20 से पुनः मॉडलित: 1606-1589 (68.3) / 1609-1560 (95.4)। Bruins & van der Plicht 2025 (PLoS One, doi:10.1371/journal.pone.0330702) मैनिंग के 2024 मॉडल को 1618-1584 (95.4) / 1612-1602 (68.3) के रूप में उद्धृत करते हैं और तर्क देते हैं कि विस्फोट अहमोस से प्राचीन है।", "94d58c09"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1649-01-01:0":{"b": ["हित्ती पुराना राज्य — हत्तुसिली प्रथम का शासन (लाबार्ना): हत्तुसिली प्रथम का काल (एचएमसी परंपरागत मान)", "17b63f56"], "d": ["हत्तुसिली प्रथम का परंपरागत शासन एचएमसी में लगभग 1650-1620; आरंभ, मुर्सिली की बाबिल 1595 की तिथि से दो 25 वर्षीय पीढ़ियाँ पीछे गिनकर निकाला जाता है। हित्ती राज्य ने मध्य कांस्य युग के अंत में मध्य अनातोलिया को एकीकृत किया था।", "8b5469d2"]},
